      when x->'payload'->'assertion'->>'predicate'='opens_during'
       and ((x->'payload'->'value'->>'startsAt')::timestamptz at time zone 'Asia/Shanghai')::date<>(instant at time zone 'Asia/Shanghai')::date then 'not_current_date' else 'eligible' end,
