  if to_char(start_time at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')<>x->>'startsAt'
   or to_char(end_time at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')<>x->>'endsAt'
