where j.request_id=p_request and auth.role()='service_role' and d.state='queued' and j.execution_xid=pg_current_xact_id_if_assigned() and j.execution_action='erase' and j.execution_digest=p.scope_digest and j.lease_id is not null and j.lease_expires_at>clock_timestamp()
