 union all select to_jsonb(t) from turn_private.result_artifacts t where t.id=any(artifacts)
 union all select to_jsonb(t) from turn_private.result_revisions t where t.artifact_id=any(artifacts)
 union all select to_jsonb(t) from turn_private.result_events t where t.artifact_id=any(artifacts)
 union all select to_jsonb(t) from turn_private.text_content t where t.turn_id=any(turns)
 union all select to_jsonb(t) from turn_private.grounded_turns t where t.turn_id=any(turns)
 union all select to_jsonb(t) from turn_private.planning_comparisons t where t.task_id=any(tasks)
 union all select to_jsonb(t) from turn_private.service_task_capacity t where t.task_id=any(tasks)
 union all select to_jsonb(t) from public.model_budget_attempts t where t.task_id=any(tasks)
 union all select to_jsonb(t) from export_private.core_jobs_v1 t where t.request_id=any(exports)
 union all select to_jsonb(t) from export_private.core_tickets_v1 t where t.request_id=any(exports)
 ) exact_touched_payloads;
 graph:=jsonb_build_object('directionsSource',directions_n,'assistantDelivery',assistant_delivery_n,'derived',derived,'trip',(select jsonb_build_array(id,owner_id,head_version,encode(sha256(convert_to(title,'UTF8')),'hex')) from public.trips where id=p_trip),'tripProposals',(select coalesce(jsonb_agg(jsonb_build_array(id,revision,base_trip_version,status,parent_proposal_id,encode(sha256(convert_to(patch::text,'UTF8')),'hex')) order by id),'[]') from public.trip_proposals where trip_id=p_trip),'selection',selection,'exports',(select coalesce(jsonb_agg(jsonb_build_array(request_id,generation,state,artifact_digest,artifact_expires_at,lease_id,lease_expires_at) order by request_id),'[]') from export_private.core_jobs_v1 where request_id=any(exports)),'threads',(select coalesce(jsonb_agg(jsonb_build_array(id,owner_id,trip_id,status) order by id),'[]') from public.chat_threads where id=any(threads)),
 'turns',(select coalesce(jsonb_agg(jsonb_build_array(id,owner_id,thread_id,trip_id,status) order by id),'[]') from public.turns where id=any(turns)),
 'tasks',(select coalesce(jsonb_agg(jsonb_build_array(id,owner_id,thread_id,goal_turn_id,last_turn_id,budget_scope_id) order by id),'[]') from turn_private.service_tasks where id=any(tasks)),
 'goals',(select coalesce(jsonb_agg(jsonb_build_array(id,owner_id,scope_version,encode(sha256(convert_to(current_text,'UTF8')),'hex')) order by id),'[]') from turn_private.assistant_goals where id=any(goals)),
