declare j scoped_edit_private.work_v1%rowtype;c scoped_edit_private.contexts_v1%rowtype;step scoped_edit_private.contexts_v1%rowtype;e jsonb;patch jsonb;derived jsonb;ops jsonb:='[]';n jsonb;r jsonb;cid uuid;begin
 if public.authorize_scoped_trip_edit_effect_v1(p_binding,'publish')->>'kind' is distinct from 'authorized' then return jsonb_build_object('kind','pending');end if;
