CREATE OR REPLACE FUNCTION public.project_planning_intake_comparison_v1(p_owner uuid, p_task uuid, p_turn uuid, p_lease uuid, p_intake_digest text, p_planning_digest text, p_observation jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare q jsonb;locale text;projection jsonb;
