declare u uuid;t public.trips%rowtype;o recovery_private.operations_v1%rowtype;p public.trip_proposals%rowtype;c recovery_private.contexts_v1%rowtype;b recovery_private.lineage_v1%rowtype;state text;version integer;profile jsonb;orders jsonb;begin
