    'noticeHash',p.notice_hash,'noticeZh',p.notice_zh,'noticeEn',p.notice_en,
    'consentState',case when c.consent_id is null then 'not_accepted' when c.revoked_at is null then 'accepted' else 'withdrawn' end);
