 return jsonb_build_object('receiptId',q->'receiptId','scope',r->'scope','policyId',q->'policyId','policyRevision',q->'policyRevision','stopEpoch',q->'stopEpoch','expiresAt',q->'expiresAt','proofBasis',q->'proofBasis');
