declare op turn_private.directions_operations_v1%rowtype;a turn_private.result_artifacts%rowtype;r turn_private.result_revisions%rowtype;
 i turn_private.assistant_directions_intakes_v1%rowtype;s turn_private.directions_result_sources_v1%rowtype;
 link_n turn_private.assistant_goal_trip_links%rowtype;trip_n public.trips%rowtype;proposal_n record;
 content_n jsonb;draft_n jsonb;days_n jsonb;replacement_n jsonb;published_n jsonb;receipt_n jsonb;qualified_n jsonb;
 source_digest_n text;next_revision_n integer;proposal_artifact_n uuid;proposal_key_n uuid;patch_n jsonb;snapshot_n jsonb;start_n date;
begin
 if u is distinct from turn_private.text_owner() or action_n not in('choose','save','edit','bind') or not turn_private.directions_input_v1(action_n,v)
  or bytes_digest_n is null or bytes_digest_n !~ '^[a-f0-9]{64}$' then raise exception 'INVALID_INPUT';end if;
 perform pg_advisory_xact_lock(hashtextextended(u::text,34));
 perform pg_advisory_xact_lock(hashtextextended('directions-op:'||u::text||':'||(v->>'operationId'),0));
 select * into op from turn_private.directions_operations_v1 where owner_id=u and operation_id=(v->>'operationId')::uuid;
 if found then
  if op.request_bytes_digest<>bytes_digest_n or op.action<>action_n then raise exception 'IDEMPOTENCY_KEY_REUSE';end if;
  if op.erased or op.artifact_id is distinct from (v->>'artifactId')::uuid or op.expected_revision is distinct from (v->>'expectedRevision')::integer then raise exception 'SERVICE_TASK_CONFLICT';end if;
  qualified_n:=public.read_result_artifact_v2(op.artifact_id,op.result_revision);
  if qualified_n->>'kind' is distinct from 'result_artifact' then raise exception 'DATA_POLICY_BLOCKED';end if;
  perform 1 from turn_private.assistant_directions_intakes_v1 x where x.message_id=op.source_message_id and x.owner_id=u and x.policy_id=policy_n;
  if not found then raise exception 'DATA_POLICY_BLOCKED';end if;
  if action_n='bind' then
   perform 1 from public.trip_proposals p where p.id=op.proposal_id and p.owner_id=u and p.trip_id=op.trip_id;
   if not found then raise exception 'SERVICE_TASK_CONFLICT';end if;
  end if;
  return op.receipt||jsonb_build_object('reused',true);
 end if;
 -- Trip locks precede original source/link/goal checks and result mutation.
 select * into a from turn_private.result_artifacts where id=(v->>'artifactId')::uuid and owner_id=u and lifecycle='active';
 if not found then raise exception 'DATA_POLICY_BLOCKED';end if;
 if a.trip_id is not null then
  select * into trip_n from public.trips where id=a.trip_id and owner_id=u for share nowait;
  if not found then raise exception 'SERVICE_TASK_CONFLICT';end if;
 end if;
 select * into a from turn_private.result_artifacts where id=a.id and owner_id=u and lifecycle='active' for update nowait;
 if not found or a.current_revision<>(v->>'expectedRevision')::integer then raise exception 'REVISION_CONFLICT';end if;
 select * into r from turn_private.result_revisions where artifact_id=a.id and owner_id=u and revision=a.current_revision;
 if not found or r.content->>'schemaVersion'<>'travel-directions/1' then raise exception 'DATA_POLICY_BLOCKED';end if;
 select * into s from turn_private.directions_result_sources_v1 where artifact_id=a.id and owner_id=u;
 select * into i from turn_private.assistant_directions_intakes_v1 where message_id=s.message_id and owner_id=u;
 if s.artifact_id is null or i.message_id is null or i.policy_id<>policy_n or i.task_id<>a.task_id or i.goal_id<>a.goal_id
  or i.task_turn_id<>r.task_turn_id or turn_private.result_state_v2(a,r)->>'current' is distinct from 'true' then raise exception 'SERVICE_TASK_CONFLICT';end if;
 source_digest_n:=turn_private.directions_current_basis_v1(u,i.message_id);
 if source_digest_n is null or source_digest_n<>s.source_digest then raise exception 'SERVICE_TASK_CONFLICT';end if;
 content_n:=r.content;next_revision_n:=r.revision+1;
 if action_n='choose' then
  if not exists(select 1 from jsonb_array_elements(content_n->'directions') d where d->>'id'=v->>'directionId') then raise exception 'INVALID_INPUT';end if;
  content_n:=content_n||jsonb_build_object('selectedDirectionId',v->'directionId','draft',null);
 elsif action_n='save' then
  if content_n->'selectedDirectionId'='null'::jsonb then raise exception 'SERVICE_TASK_CONFLICT';end if;
  -- An existing saved/edited draft is preserved by another explicit save.
  draft_n:=content_n->'draft';
  if draft_n='null'::jsonb then draft_n:=turn_private.directions_relative_projection_v1(i.intake,(select locale from turn_private.assistant_messages where id=i.message_id and owner_id=u),content_n->>'selectedDirectionId');end if;
  content_n:=content_n||jsonb_build_object('draft',draft_n);
 elsif action_n='edit' then
  draft_n:=content_n->'draft';if draft_n='null'::jsonb then raise exception 'SERVICE_TASK_CONFLICT';end if;
  for replacement_n in select value from jsonb_array_elements(v->'replacements') loop
   if not exists(select 1 from jsonb_array_elements(draft_n->'days') d where d->'ordinal'=replacement_n->'ordinal') then raise exception 'INVALID_INPUT';end if;
  end loop;
  select coalesce(jsonb_agg(coalesce((select e from jsonb_array_elements(v->'replacements') e where e->'ordinal'=d->'ordinal'),d) order by (d->>'ordinal')::integer),'[]') into days_n from jsonb_array_elements(draft_n->'days') d;
  content_n:=content_n||jsonb_build_object('draft',draft_n||jsonb_build_object('days',days_n));
 else
  if a.trip_id is distinct from (v->>'tripId')::uuid or trip_n.head_version is distinct from (v->>'expectedTripVersion')::integer then raise exception 'SERVICE_TASK_CONFLICT';end if;
  draft_n:=content_n->'draft';if draft_n='null'::jsonb or content_n->'selectedDirectionId'='null'::jsonb or jsonb_array_length(draft_n->'days')=0 then raise exception 'SERVICE_TASK_CONFLICT';end if;
  start_n:=(v->>'startDate')::date;
  if i.intake->'dates'<>'null'::jsonb and (i.intake->'dates'->>'startDate'<>v->>'startDate'
   or (i.intake->'dates'->>'endDate')::date<>start_n+jsonb_array_length(draft_n->'days')-1) then raise exception 'SERVICE_TASK_CONFLICT';end if;
  select * into link_n from turn_private.assistant_goal_trip_links where goal_id=i.goal_id and owner_id=u and conversation_id=i.conversation_id and trip_id=trip_n.id for share nowait;
  if not found or link_n.terminal_unlinked or link_n.source_kind<>'native_user_confirmed' or link_n.goal_scope_version<>i.goal_version or link_n.trip_head_version<>trip_n.head_version then raise exception 'SERVICE_TASK_CONFLICT';end if;
  snapshot_n:=public.trip_content_snapshot(trip_n.id,trip_n.title);
  patch_n:=turn_private.directions_append_patch_v1(draft_n,snapshot_n,start_n,'dir_'||replace(v->>'operationId','-',''),trip_n.head_version);
  select * into proposal_n from public.create_trip_proposal_patch(trip_n.id,patch_n);
  if proposal_n.proposal_id is null or proposal_n.revision not between 1 and 1000 then raise exception 'REVISION_CONFLICT';end if;
  proposal_artifact_n:=gen_random_uuid();proposal_key_n:=gen_random_uuid();
  published_n:=turn_private.publish_result_v2(u,proposal_artifact_n,0,proposal_key_n,i.task_id,i.goal_id,i.message_id,trip_n.id,trip_n.head_version,i.goal_version,i.memory_basis,
   jsonb_build_object('schemaVersion','change-proposal-reference/1','proposalId',proposal_n.proposal_id,'proposalRevision',proposal_n.revision,'actions','[]'::jsonb),'[]',true);
  if published_n->>'kind' is distinct from 'published' then raise exception 'SERVICE_TASK_CONFLICT';end if;
  receipt_n:=jsonb_build_object('kind','proposal_created','artifactId',a.id,'revision',r.revision,'reused',false,'tripId',trip_n.id,'tripVersion',trip_n.head_version,
   'proposalId',proposal_n.proposal_id,'proposalRevision',proposal_n.revision,'proposalArtifactId',proposal_artifact_n,'proposalArtifactRevision',(published_n->>'revision')::integer);
  insert into turn_private.directions_operations_v1(operation_id,owner_id,session_id,action,request_bytes_digest,artifact_id,source_message_id,task_turn_id,expected_revision,result_revision,source_digest,trip_id,proposal_id,proposal_artifact_id,receipt)
  values((v->>'operationId')::uuid,u,(auth.jwt()->>'session_id')::uuid,action_n,bytes_digest_n,a.id,i.message_id,i.task_turn_id,r.revision,r.revision,source_digest_n,trip_n.id,proposal_n.proposal_id,proposal_artifact_n,receipt_n);
  return receipt_n;
 end if;
 if not turn_private.valid_travel_directions_v1(content_n) or next_revision_n>1000 then raise exception 'INVALID_INPUT';end if;
 receipt_n:=jsonb_build_object('kind',case action_n when 'choose' then 'selected' when 'save' then 'saved' else 'revised' end,'artifactId',a.id,'revision',next_revision_n,'reused',false);
 insert into turn_private.directions_operations_v1(operation_id,owner_id,session_id,action,request_bytes_digest,artifact_id,source_message_id,task_turn_id,expected_revision,result_revision,source_digest,output_content_digest,receipt)
 values((v->>'operationId')::uuid,u,(auth.jwt()->>'session_id')::uuid,action_n,bytes_digest_n,a.id,i.message_id,i.task_turn_id,r.revision,next_revision_n,source_digest_n,encode(sha256(convert_to(content_n::text,'UTF8')),'hex'),receipt_n);
 published_n:=turn_private.publish_result_v2(u,a.id,r.revision,(v->>'operationId')::uuid,a.task_id,a.goal_id,a.input_message_id,a.trip_id,r.trip_version,r.goal_version,r.memory_basis,content_n,r.evidence_basis,true);
 if published_n->>'kind' is distinct from 'published' or (published_n->>'revision')::integer<>next_revision_n then raise exception 'REVISION_CONFLICT';end if;
 return receipt_n;
exception when lock_not_available then raise exception 'SERVICE_TASK_CONFLICT';
end

