  or not exists(select 1 from turn_private.assistant_directions_intakes_v1 i where i.task_turn_id=p_turn and i.owner_id=p_owner and turn_private.directions_current_basis_v1(p_owner,i.message_id) is not null) then raise exception 'SERVICE_TASK_CONFLICT';end if;
