 if not found or w.execution_mode<>'travel_directions_v1' or w.state<>'leased'
  or w.lease_token is distinct from p_lease_token or w.expires_at<=clock_timestamp() then return jsonb_build_object('kind','blocked');end if;
 select * into s from turn_private.directions_result_sources_v1 where task_turn_id=p_turn_id and owner_id=w.owner_id;
 if not found then return jsonb_build_object('kind','blocked');end if;
 select * into i from turn_private.assistant_directions_intakes_v1 where message_id=s.message_id and owner_id=w.owner_id and task_turn_id=p_turn_id;
 if not found then return jsonb_build_object('kind','blocked');end if;
 -- Original Text cap stays8000 even when a preserved edited Result is64KB.
 -- Canonical admission separately binds actual Result content digest; the Turn
 -- stores its real human-readable deterministic completion, not a content copy.
 if encode(sha256(convert_to(p_text,'UTF8')),'hex')<>s.initial_output_digest then return jsonb_build_object('kind','blocked');end if;
 actual_n:=turn_private.directions_current_basis_v1(w.owner_id,i.message_id);
 if actual_n is null or actual_n<>s.source_digest then return jsonb_build_object('kind','blocked');end if;
