 -- event. The enclosing original wrapper verifies readability and settles the
 -- logical Task reservation. No provider/model attempt or usage is synthesized.
 update turn_private.text_content set output_kind='answered',output_text=p_text where turn_id=p_turn_id and owner_id=w.owner_id and hidden_at is null;
 if not found then return jsonb_build_object('kind','blocked');end if;
 perform turn_private.terminal(p_turn_id,'completed',w.attempt);
 return jsonb_build_object('kind','finished');
exception when invalid_text_representation then raise exception 'INVALID_INPUT';
end $function$

