declare d jsonb;item_n jsonb;ops_n jsonb:='[]';day_id_n text;item_id_n text;date_n text;n integer;patch_n jsonb;
begin
 if jsonb_typeof(draft_n->'days') is distinct from 'array' or jsonb_array_length(draft_n->'days') not between 1 and 30
  or prefix_n !~ '^[A-Za-z0-9_-]{1,40}$' or start_n is null then raise exception 'INVALID_INPUT';end if;
 for d in select value from jsonb_array_elements(draft_n->'days') loop
  date_n:=to_char(start_n+(d->>'ordinal')::integer-1,'YYYY-MM-DD');day_id_n:=prefix_n||'_d'||(d->>'ordinal');
  if exists(select 1 from jsonb_array_elements(snapshot_n->'days') old where old->>'date'=date_n or old->>'id'=day_id_n)
   or exists(select 1 from jsonb_array_elements(snapshot_n->'days') old cross join lateral jsonb_array_elements(coalesce(old->'items','[]')) item where item->>'id'=day_id_n) then raise exception 'SERVICE_TASK_CONFLICT';end if;
  ops_n:=ops_n||jsonb_build_array(jsonb_build_object('kind','upsert_day','dayId',day_id_n,'date',date_n,'timeZone','Asia/Shanghai'));
  n:=0;for item_n in select value from jsonb_array_elements(d->'activities') loop
   n:=n+1;item_id_n:=day_id_n||'_i'||n;
   if exists(select 1 from jsonb_array_elements(snapshot_n->'days') old where old->>'id'=item_id_n)
    or exists(select 1 from jsonb_array_elements(snapshot_n->'days') old cross join lateral jsonb_array_elements(coalesce(old->'items','[]')) item where item->>'id'=item_id_n) then raise exception 'SERVICE_TASK_CONFLICT';end if;
   ops_n:=ops_n||jsonb_build_array(jsonb_build_object('kind','upsert_item','dayId',day_id_n,'itemId',item_id_n,'title',item_n));
  end loop;
 end loop;
 patch_n:=jsonb_build_object('expectedVersion',version_n,'operations',ops_n);
 perform public.apply_trip_content_patch(snapshot_n,patch_n); -- original caps/closed Patch validation
 return patch_n;
end

