declare s turn_private.directions_result_sources_v1%rowtype;
 i turn_private.assistant_directions_intakes_v1%rowtype;actual_n text;content_n text;prior_r turn_private.result_revisions%rowtype;
begin
 if not turn_private.valid_travel_directions_v1(v) then return jsonb_build_object('readable',false,'current',false);end if;
 select * into s from turn_private.directions_result_sources_v1 where task_turn_id=task_turn_n and owner_id=u;
 if not found then return jsonb_build_object('readable',false,'current',false);end if;
 select * into i from turn_private.assistant_directions_intakes_v1 where message_id=s.message_id and owner_id=u and task_turn_id=task_turn_n;
 if not found or v->'intake' is distinct from i.intake
  or (v->'draft'<>'null'::jsonb and v->'draft'->>'paceSource'='profile')
  or not turn_private.planning_policy_current(i.planning_policy_id)
  or not exists(select 1 from turn_private.planning_consents c where c.owner_id=u and c.policy_id=i.planning_policy_id and c.consent_id=i.planning_consent_id and c.revoked_at is null) then return jsonb_build_object('readable',false,'current',false);end if;
 content_n:=encode(sha256(convert_to(v::text,'UTF8')),'hex');
 -- Immutable original revisions hold content. Source/action metadata contains
 -- only digest/provenance; a generic service publisher cannot invent a choice.
 if content_n<>s.initial_content_digest and not exists(select 1 from turn_private.directions_operations_v1 o
  where o.owner_id=u and o.artifact_id=s.artifact_id and o.source_message_id=i.message_id and o.task_turn_id=task_turn_n
   and not o.erased and o.action in('choose','save','edit') and o.output_content_digest=content_n and o.source_digest=s.source_digest) then
  return jsonb_build_object('readable',false,'current',false);
 end if;
 if s.previous_artifact_id is not null then
  select * into prior_r from turn_private.result_revisions where artifact_id=s.previous_artifact_id and revision=s.previous_revision and owner_id=u;
  if not found or prior_r.content->'intake' is distinct from i.intake or prior_r.memory_basis is distinct from i.memory_basis
   or not turn_private.directions_history_readable_v1(u,s.previous_artifact_id,s.previous_revision,i.goal_id) then
   return jsonb_build_object('readable',false,'current',false);
  end if;
 end if;
 actual_n:=turn_private.directions_current_basis_v1(u,i.message_id);
 -- Original common Result state separately qualifies historical readability,
 -- original Memory/Task/Trip and evidence. New source staleness grants no action.
 return jsonb_build_object('readable',true,'current',actual_n is not null and actual_n=s.source_digest);
end

