declare r record;page_n jsonb:='[]';item_n jsonb;cursor_n uuid;more_n boolean:=false;delivered_n integer:=0;candidate_n integer:=0;envelope_n jsonb;
begin
 if auth.role() is distinct from 'service_role' or owner_n is null then raise exception 'FORBIDDEN';end if;
 if section_n is null or section_n not in('directionIntakes','directionSources','directionOperations') or limit_n is null or limit_n not between 1 and 100 then raise exception 'INVALID_INPUT';end if;
 if after_n is not null and not exists(
  select 1 from turn_private.assistant_directions_intakes_v1 where section_n='directionIntakes' and owner_id=owner_n and message_id=after_n
  union all select 1 from turn_private.directions_result_sources_v1 where section_n='directionSources' and owner_id=owner_n and artifact_id=after_n
  union all select 1 from turn_private.directions_operations_v1 where section_n='directionOperations' and owner_id=owner_n and operation_id=after_n) then raise exception 'STALE_EXPORT_CURSOR';end if;
 for r in select * from(
  select i.message_id id,jsonb_build_object('messageId',i.message_id,'intakeRevision',i.intake_revision,'goalId',i.goal_id,'conversationId',i.conversation_id,'taskId',i.task_id,'taskTurnId',i.task_turn_id,
   'messageSequence',i.message_sequence,'goalVersion',i.goal_version,'policyId',i.policy_id,'consentId',i.consent_id,'planningPolicyId',i.planning_policy_id,'planningConsentId',i.planning_consent_id,
   'idempotencyKey',i.idempotency_key,'requestBytesDigest',i.request_bytes_digest,'intake',i.intake,'memoryBasis',i.memory_basis,'createdAt',i.created_at) item
   from turn_private.assistant_directions_intakes_v1 i where section_n='directionIntakes' and i.owner_id=owner_n and (after_n is null or i.message_id>after_n)
  union all select s.artifact_id,jsonb_build_object('artifactId',s.artifact_id,'messageId',s.message_id,'taskTurnId',s.task_turn_id,'sourceDigest',s.source_digest,
   'initialContentDigest',s.initial_content_digest,'initialOutputDigest',s.initial_output_digest,'previousArtifactId',s.previous_artifact_id,'previousRevision',s.previous_revision,'publicationKey',s.publication_key,'createdAt',s.created_at)
   from turn_private.directions_result_sources_v1 s where section_n='directionSources' and s.owner_id=owner_n and (after_n is null or s.artifact_id>after_n)
  union all select o.operation_id,jsonb_build_object('operationId',o.operation_id,'sessionId',o.session_id,'action',o.action,'requestBytesDigest',o.request_bytes_digest,'erased',o.erased,
   'artifactId',o.artifact_id,'sourceMessageId',o.source_message_id,'taskTurnId',o.task_turn_id,'expectedRevision',o.expected_revision,'resultRevision',o.result_revision,'sourceDigest',o.source_digest,
   'outputContentDigest',o.output_content_digest,'tripId',o.trip_id,'proposalId',o.proposal_id,'proposalArtifactId',o.proposal_artifact_id,'receipt',o.receipt,'createdAt',o.created_at)
   from turn_private.directions_operations_v1 o where section_n='directionOperations' and o.owner_id=owner_n and (after_n is null or o.operation_id>after_n)
 ) rows order by id limit limit_n+1 loop
  candidate_n:=candidate_n+1;if delivered_n>=limit_n then more_n:=true;exit;end if;
