declare a turn_private.result_artifacts%rowtype;r turn_private.result_revisions%rowtype;
 s turn_private.directions_result_sources_v1%rowtype;i turn_private.assistant_directions_intakes_v1%rowtype;
 seen_n uuid[]:=array[]::uuid[];bytes_n bigint:=0;content_n text;state_n jsonb;
 next_artifact_n uuid:=artifact_n;next_revision_n integer:=revision_n;
begin
 if u is null or goal_n is null or next_artifact_n is null or next_revision_n not between 1 and 1000 then return false;end if;
 while next_artifact_n is not null loop
  if next_artifact_n=any(seen_n) or cardinality(seen_n)>=4100 then return false;end if;
  seen_n:=seen_n||array[next_artifact_n];
  select * into a from turn_private.result_artifacts where id=next_artifact_n and owner_id=u and goal_id=goal_n and lifecycle='active';
  if not found then return false;end if;
  select * into r from turn_private.result_revisions where artifact_id=a.id and revision=next_revision_n and owner_id=u;
  if not found or r.evidence_basis is distinct from '[]'::jsonb or not turn_private.valid_travel_directions_v1(r.content)
   or (r.content->'draft'<>'null'::jsonb and r.content->'draft'->>'paceSource'='profile') then return false;end if;
  -- Existing archive variant policy is not extended by this new provenance read.
  if a.trip_id is not null and (exists(select 1 from public.trip_archives where trip_id=a.trip_id and owner_id=u)
   or exists(select 1 from privacy_private.trip_deletions where trip_id=a.trip_id)) then return false;end if;
  state_n:=turn_private.comparison_common_basis_state(a,r);
  if state_n->>'readable' is distinct from 'true' then return false;end if;
  select * into s from turn_private.directions_result_sources_v1 where artifact_id=a.id and owner_id=u and task_turn_id=r.task_turn_id;
  if not found or a.source_result_id is distinct from s.previous_artifact_id then return false;end if;
  select * into i from turn_private.assistant_directions_intakes_v1 where message_id=s.message_id and owner_id=u and goal_id=goal_n and task_turn_id=r.task_turn_id;
  if not found or r.content->'intake' is distinct from i.intake or r.memory_basis is distinct from i.memory_basis
   or not turn_private.planning_policy_current(i.planning_policy_id)
   or not exists(select 1 from turn_private.planning_consents c where c.owner_id=u and c.policy_id=i.planning_policy_id and c.consent_id=i.planning_consent_id and c.revoked_at is null) then return false;end if;
  content_n:=encode(sha256(convert_to(r.content::text,'UTF8')),'hex');
  if content_n<>s.initial_content_digest and not exists(select 1 from turn_private.directions_operations_v1 o
   where o.owner_id=u and o.artifact_id=a.id and o.source_message_id=i.message_id and o.task_turn_id=r.task_turn_id
    and not o.erased and o.action in('choose','save','edit') and o.result_revision=r.revision
    and o.output_content_digest=content_n and o.source_digest=s.source_digest) then return false;end if;
  bytes_n:=bytes_n+octet_length(jsonb_build_array(to_jsonb(a),to_jsonb(r),to_jsonb(s),to_jsonb(i))::text);
  if bytes_n>1000000 then return false;end if;
  next_artifact_n:=s.previous_artifact_id;next_revision_n:=s.previous_revision;
 end loop;
 return true;
end

