declare result_n jsonb;
begin
 result_n:=jsonb_build_object('schemaVersion','travel-directions/1',
  'title',case when locale_n='zh' then '你的旅行方向' else 'Your travel directions' end,
  'summary',case when locale_n='zh' then '先比较体验和取舍；选方向、保存相对日草稿和确认行程分别操作。日期、交通、营业时间与价格尚未核实。' else 'Compare experiences and tradeoffs first. Choosing a direction, saving a relative-day draft and confirming a Trip are separate actions. Dates, transport, opening hours and prices are unverified.' end,
  'intake',i,'directions',turn_private.directions_options_v1(i,locale_n),'selectedDirectionId',null,'draft',null,'actions','[]'::jsonb);
 if not turn_private.valid_travel_directions_v1(result_n) then raise exception 'INVALID_INPUT';end if;
 return result_n;
end

declare keys_n text[];k text;e jsonb;ids_n uuid[]:=array[]::uuid[];ordinals_n integer[]:=array[]::integer[];date_n date;
begin
 if action_n is null or jsonb_typeof(v) is distinct from 'object' then return false;end if;
 if action_n in('basis','intake') then
  return turn_private.directions_exact_v1(v,array['conversationId','goalId']) and turn_private.directions_uuid_v1(v->'conversationId') and turn_private.directions_uuid_v1(v->'goalId');
 end if;
 if action_n='submit' then
  keys_n:=array['conversationId','goalId','expectedGoalVersion','parentMessageId','messageId','messageKey','threadId','turnId','taskId','taskKey','planningPolicyId','locale','text','memoryBasis','expectedSourceSequence','expectedIntakeRevision','expectedIntakeDigest','intake','useSavedPace','expectedProfileRevision'];
  if not turn_private.directions_exact_v1(v,keys_n) then return false;end if;
  foreach k in array array['conversationId','goalId','parentMessageId','messageId','messageKey','threadId','turnId','taskId','taskKey','planningPolicyId'] loop
   if not turn_private.directions_uuid_v1(v->k) then return false;end if;
  end loop;
  if (v->>'taskId')::uuid=(v->>'turnId')::uuid or (v->>'messageId')::uuid=(v->>'parentMessageId')::uuid
   or not turn_private.directions_integer_v1(v->'expectedGoalVersion',1,9999)
   or not turn_private.directions_integer_v1(v->'expectedSourceSequence',1,999999)
   or not turn_private.directions_integer_v1(v->'expectedIntakeRevision',0,999)
   or ((v->>'expectedIntakeRevision')::integer=0 and v->'expectedIntakeDigest'<>'null'::jsonb)
   or ((v->>'expectedIntakeRevision')::integer>0 and (jsonb_typeof(v->'expectedIntakeDigest')<>'string' or v->>'expectedIntakeDigest' !~ '^[a-f0-9]{64}$'))
   or jsonb_typeof(v->'locale') is distinct from 'string' or v->>'locale' not in('zh','en')
   or jsonb_typeof(v->'text') is distinct from 'string' or not turn_private.valid_text(v->>'text',4000)
   or not turn_private.valid_directions_intake_v1(v->'intake')
   or jsonb_typeof(v->'useSavedPace') is distinct from 'boolean'
   or (v->'expectedProfileRevision'<>'null'::jsonb and not turn_private.directions_integer_v1(v->'expectedProfileRevision',0,9007199254740990))
   or (v->'useSavedPace'='true'::jsonb and v->'expectedProfileRevision'='null'::jsonb)
   or jsonb_typeof(v->'memoryBasis') is distinct from 'array' or jsonb_array_length(v->'memoryBasis')>3 then return false;end if;
  for e in select value from jsonb_array_elements(v->'memoryBasis') loop
   if not turn_private.directions_exact_v1(e,array['id','revision']) or not turn_private.directions_uuid_v1(e->'id')
    or not turn_private.directions_integer_v1(e->'revision',1,999999999999999) then return false;end if;
   if (e->>'id')::uuid=any(ids_n) then return false;end if;ids_n:=ids_n||array[(e->>'id')::uuid];
  end loop;
  return true;
 end if;
 keys_n:=array['artifactId','expectedRevision','operationId'];
 if action_n='choose' then keys_n:=keys_n||array['directionId'];
 elsif action_n='edit' then keys_n:=keys_n||array['replacements'];
 elsif action_n='bind' then keys_n:=keys_n||array['tripId','expectedTripVersion','startDate'];
 elsif action_n<>'save' then return false;end if;
 if not turn_private.directions_exact_v1(v,keys_n) or not turn_private.directions_uuid_v1(v->'artifactId') or not turn_private.directions_uuid_v1(v->'operationId')
  or not turn_private.directions_integer_v1(v->'expectedRevision',1,case when action_n='bind' then 1000 else 999 end) then return false;end if;
 if action_n='save' then return true;end if;
 if action_n='choose' then return coalesce(jsonb_typeof(v->'directionId')='string' and v->>'directionId' in('depth','breadth'),false);end if;
 if action_n='bind' then
  if not turn_private.directions_uuid_v1(v->'tripId') or not turn_private.directions_integer_v1(v->'expectedTripVersion',0,2147483647)
   or jsonb_typeof(v->'startDate') is distinct from 'string' or v->>'startDate' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then return false;end if;
  date_n:=(v->>'startDate')::date;return date_n::text=v->>'startDate';
 end if;
 if jsonb_typeof(v->'replacements') is distinct from 'array' or jsonb_array_length(v->'replacements') not between 1 and 30 then return false;end if;
 for e in select value from jsonb_array_elements(v->'replacements') loop
  if not turn_private.directions_exact_v1(e,array['ordinal','destination','activities']) or not turn_private.directions_integer_v1(e->'ordinal',1,30)
   or not turn_private.directions_text_v1(e->'destination',80) or not turn_private.directions_strings_v1(e->'activities',8,160) or jsonb_array_length(e->'activities')=0 then return false;end if;
  if (e->>'ordinal')::integer=any(ordinals_n) then return false;end if;ordinals_n:=ordinals_n||array[(e->>'ordinal')::integer];
 end loop;return true;
exception when invalid_text_representation or numeric_value_out_of_range or invalid_datetime_format or datetime_field_overflow then return false;
end

