declare spec record;raw_n text;i turn_private.assistant_directions_intakes_v1%rowtype;m jsonb;
begin
 if relation_n not in('turn_private.assistant_directions_intakes_v1','turn_private.directions_result_sources_v1','turn_private.directions_operations_v1') then return;end if;
 for spec in select * from(values('artifact_id','artifactIds'),('previous_artifact_id','artifactIds'),('proposal_artifact_id','artifactIds'),('message_id','messageIds'),('source_message_id','messageIds'),('task_turn_id','turnIds'),('task_id','taskIds'),('goal_id','goalIds'),('conversation_id','conversationIds')) refs(column_n,kind_n) loop
  raw_n:=v->>spec.column_n;
  if raw_n is not null then
   if not turn_private.directions_uuid_v1(to_jsonb(raw_n)) then raise exception 'INVALID_DIRECTIONS_REFERENCE';end if;
   return query select spec.kind_n::text,raw_n::uuid;
  end if;
 end loop;
 -- Purpose metadata has no duplicate parent fields: resolve the original intake
 -- by exact existing source identity and owner, never arbitrary UUID guessing.
 if relation_n<>'turn_private.assistant_directions_intakes_v1' then
  select * into i from turn_private.assistant_directions_intakes_v1 where message_id=coalesce(nullif(v->>'message_id',''),nullif(v->>'source_message_id',''))::uuid and owner_id=(v->>'owner_id')::uuid;
  if found then
   return query select 'conversationIds'::text,i.conversation_id union select 'goalIds',i.goal_id union select 'taskIds',i.task_id;
  end if;
 end if;
end

