declare b jsonb;i turn_private.assistant_directions_intakes_v1%rowtype;d text;
 link_n turn_private.assistant_goal_trip_links%rowtype;trip_n public.trips%rowtype;pace_n jsonb;
begin
 b:=turn_private.directions_write_basis_v1(u,policy_n,conversation_n,goal_n);
 if b->>'kind'='unavailable' then return b;end if;
 select * into i from turn_private.assistant_directions_intakes_v1 where goal_id=goal_n and owner_id=u and conversation_id=conversation_n order by intake_revision desc limit 1;
 if not found then return jsonb_build_object('kind','unavailable','reason','intake_unrecorded');end if;
 d:=turn_private.directions_current_basis_v1(u,i.message_id);
 if d is null then return jsonb_build_object('kind','unavailable','reason','stale_basis');end if;
 select * into link_n from turn_private.assistant_goal_trip_links where goal_id=goal_n and owner_id=u and conversation_id=conversation_n and not terminal_unlinked and trip_id is not null;
 if found then
  select * into trip_n from public.trips where id=link_n.trip_id and owner_id=u;
  if not found or exists(select 1 from privacy_private.trip_deletions where trip_id=link_n.trip_id)
   or exists(select 1 from public.trip_archives where trip_id=link_n.trip_id and owner_id=u) then return jsonb_build_object('kind','unavailable','reason','stale_basis');end if;
  -- Existing local-only projection may be displayed by its original consumer.
  -- This read is not server planning permission; submit.useSavedPace still denies.
  if exists(select 1 from identity_private.mobile_login_proofs p where p.session_id=(auth.jwt()->>'session_id')::uuid)
   or exists(select 1 from identity_private.mobile_attempts p where p.session_id=(auth.jwt()->>'session_id')::uuid) then
   pace_n:=public.native_task_travel_pace_v1(jsonb_build_object('tripId',trip_n.id,'currentPace',null,'useSaved',true));
   if pace_n->>'source' is distinct from 'profile' then pace_n:=null;end if;
  end if;
 end if;
 return jsonb_build_object('kind','directions_intake','schemaVersion','travel-directions-current-basis/1','conversationId',i.conversation_id,'goalId',i.goal_id,
  'goalVersion',i.goal_version,'inputMessageId',i.message_id,'inputSequence',i.message_sequence,'intakeRevision',i.intake_revision,'intakeDigest',d,
  'intake',i.intake,'memoryBasis',i.memory_basis,'tripId',trip_n.id,'tripVersion',trip_n.head_version,'profilePace',pace_n);
end

