 ordinal_n integer;index_n integer;activity_index_n integer;destination_n text;unallocated_n text;
 pace_n text;pace_source_n text;
begin
 if not turn_private.valid_directions_intake_v1(i) or locale_n is null or locale_n not in('zh','en')
  or direction_n is null or not exists(select 1 from jsonb_array_elements(turn_private.directions_options_v1(i,locale_n)) d where d->>'id'=direction_n) then raise exception 'INVALID_INPUT';end if;
 duration_n:=(i->>'durationDays')::integer;destinations_n:=jsonb_array_length(i->'destinations');interests_n:=jsonb_array_length(i->'interests');
 pace_n:=i->>'currentPace';pace_source_n:=case when pace_n is null then 'none' else 'current_input' end;
 limits_n:=jsonb_build_array(case when locale_n='zh' then '日期、交通、营业时间与价格尚未核实；这是相对日想法，不是可执行行程。' else 'Dates, transport, opening hours and prices are unverified; this is a relative-day idea, not an executable itinerary.' end);
 if i->'budget'<>'null'::jsonb then limits_n:=limits_n||jsonb_build_array(case when locale_n='zh' then '预算已保留；没有报价依据，不能证明安排符合预算。' else 'Your budget is retained; without price evidence, affordability is unknown.' end);end if;
 if interests_n=0 then limits_n:=limits_n||jsonb_build_array(case when locale_n='zh' then '兴趣尚未指定；这里只保留自主探索意图，主题和地点待你选择。' else 'Interests are unspecified; only exploration intentions are reserved, with themes and places for you to choose.' end);end if;
 if duration_n is null then limits_n:=limits_n||jsonb_build_array(case when locale_n='zh' then '天数未定，可跳过后再补。' else 'Duration is unknown and can be added later.' end);end if;
 if destinations_n=0 then limits_n:=limits_n||jsonb_build_array(case when locale_n='zh' then '目的地未定，可先选方向。' else 'Destination is unknown; you can choose a direction first.' end);end if;
 if duration_n is not null and destinations_n>0 then
  used_n:=least(duration_n,destinations_n);
  if used_n<destinations_n then
   select string_agg(value#>>'{}',', ' order by ord) into unallocated_n from jsonb_array_elements(i->'destinations') with ordinality d(value,ord) where ord>used_n;
   limits_n:=limits_n||jsonb_build_array((case when locale_n='zh' then '本草稿未分配目的地：' else 'Destinations not allocated in this draft: ' end)||unallocated_n);
  end if;
  for ordinal_n in 1..duration_n loop
   index_n:=least(used_n-1,floor((ordinal_n-1)::numeric*used_n/duration_n)::integer);
   destination_n:=i->'destinations'->>index_n;
   count_n:=case when pace_n='relaxed' then 1 when direction_n='breadth' or pace_n='packed' then 2 else 1 end;
   activity_n:='[]';
   if interests_n>0 then
    for activity_index_n in 0..least(count_n,interests_n)-1 loop
     activity_n:=activity_n||jsonb_build_array((case when direction_n='depth' then (case when locale_n='zh' then '深入体验：' else 'Explore in depth: ' end) else (case when locale_n='zh' then '比较不同体验：' else 'Compare experiences of: ' end) end)||(i->'interests'->>((ordinal_n-1+activity_index_n)%interests_n)));
    end loop;
   else activity_n:=jsonb_build_array(case when direction_n='depth' then (case when locale_n='zh' then '保留留白，随性探索' else 'Leave space for spontaneous exploration' end) else (case when locale_n='zh' then '比较可自选的探索主题，具体内容待定' else 'Compare exploration themes you choose; details remain open' end) end);end if;
   days_n:=days_n||jsonb_build_array(jsonb_build_object('ordinal',ordinal_n,'destination',destination_n,'activities',activity_n));
  end loop;
 end if;
 result_n:=jsonb_build_object('directionId',direction_n,'requestedDays',i->'durationDays','days',days_n,
  'coverage',case when jsonb_array_length(days_n)>0 and destinations_n<=jsonb_array_length(days_n) then 'complete_relative' else 'partial_relative' end,
  'limitations',limits_n,'pace',pace_n,'paceSource',pace_source_n);
 if not turn_private.valid_directions_relative_v1(result_n,i) then raise exception 'INVALID_INPUT';end if;
 return result_n;
end

