declare s text; units integer;whitespace_n text:=U&'\0009\000A\000B\000C\000D\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF';
begin
 if jsonb_typeof(v) is distinct from 'string' or max_n not between 1 and 3000 then return false;end if;
 s:=v#>>'{}';
 if length(s)=0 or length(s)>max_n or s ~ ('['||chr(1)||'-'||chr(31)||']')
  or strpos(whitespace_n,left(s,1))>0 or strpos(whitespace_n,right(s,1))>0 then return false;end if;
 -- JS wire limits count UTF16 units, including two units for supplementary chars.
 select coalesce(sum(case when ascii(c)>65535 then 2 else 1 end),0) into units from regexp_split_to_table(s,'') c;
 return units between 1 and max_n;
end

