 m turn_private.assistant_messages%rowtype;i turn_private.assistant_directions_intakes_v1%rowtype;
 digest_n text;revision_n integer:=0;
begin
 if u is null or policy_n is null or conversation_n is null or goal_n is null then raise exception 'INVALID_INPUT';end if;
 select * into a from turn_private.assistant_conversations where id=conversation_n and owner_id=u and policy_id=policy_n;
 select * into g from turn_private.assistant_goals where id=goal_n and owner_id=u and conversation_id=conversation_n;
 if a.id is null or g.id is null or g.trip_terminal or not turn_private.text_policy_current(policy_n)
  or not exists(select 1 from turn_private.text_consents c where c.owner_id=u and c.policy_id=policy_n and c.consent_id=a.consent_id and c.revoked_at is null) then return jsonb_build_object('kind','unavailable','reason','blocked');end if;
 select * into m from turn_private.assistant_messages where goal_id=g.id and owner_id=u and conversation_id=a.id order by sequence desc limit 1;
 if not found or m.policy_id<>policy_n or m.consent_id<>a.consent_id or m.sequence not between 1 and 999999
  or g.scope_version not between 1 and 9999 or a.next_sequence>1000000 then return jsonb_build_object('kind','unavailable','reason','stale_basis');end if;
 select * into i from turn_private.assistant_directions_intakes_v1 where goal_id=g.id and owner_id=u order by intake_revision desc limit 1;
