  revision_n:=i.intake_revision;if revision_n>999 then return jsonb_build_object('kind','unavailable','reason','stale_basis');end if;
  digest_n:=turn_private.directions_current_basis_v1(u,i.message_id);
  if digest_n is null then
   -- Explicit fresh linked-scope/correction may append a new source while the
   -- old result stays stale. This token binds the actual current parent/scope
   -- and exact immutable prior intake; it never makes old content current.
   digest_n:=encode(sha256(convert_to(jsonb_build_object('schemaVersion','travel-directions-write-cas/1','ownerId',u,
    'conversationId',a.id,'goalId',g.id,'goalVersion',g.scope_version,'parentMessageId',m.id,'messageSequence',m.sequence,
    'policyId',policy_n,'consentId',a.consent_id,'priorMessageId',i.message_id,'intakeRevision',i.intake_revision,
    'priorRequestBytesDigest',i.request_bytes_digest)::text,'UTF8')),'hex');
  end if;
 end if;
 return jsonb_build_object('kind','directions_write_basis','conversationId',a.id,'goalId',g.id,'goalVersion',g.scope_version,
  'parentMessageId',m.id,'messageSequence',m.sequence,'intakeRevision',revision_n,'intakeDigest',digest_n,'policyId',policy_n);
end

