declare r jsonb;
begin
 -- Existing original proof/xid and selected entity guards are mandatory.
 -- Operation receipts become irreversible minimal replay fences before parents.
 for r in select value from jsonb_array_elements(witness_n->'rows') where value->>'effect'='scrub' loop
  if r->>'table'<>'turn_private.directions_operations_v1' then raise exception 'UNKNOWN_DIRECTIONS_RELATION';end if;
  update turn_private.directions_operations_v1 set erased=true,artifact_id=null,source_message_id=null,task_turn_id=null,expected_revision=null,result_revision=null,source_digest=null,output_content_digest=null,trip_id=null,proposal_id=null,proposal_artifact_id=null,receipt=null
   where owner_id=u and operation_id=(r->'key'->>'operation_id')::uuid and not erased;
  if not found then raise exception 'DIRECTIONS_SOURCE_CHANGED';end if;
 end loop;
 for r in select value from jsonb_array_elements(witness_n->'rows') where value->>'effect'='erase' order by case value->>'table' when 'turn_private.directions_result_sources_v1' then 0 else 1 end loop
  case r->>'table'
   when 'turn_private.directions_result_sources_v1' then delete from turn_private.directions_result_sources_v1 where owner_id=u and artifact_id=(r->'key'->>'artifact_id')::uuid;
   when 'turn_private.assistant_directions_intakes_v1' then delete from turn_private.assistant_directions_intakes_v1 where owner_id=u and message_id=(r->'key'->>'message_id')::uuid;
   else raise exception 'UNKNOWN_DIRECTIONS_RELATION';
  end case;
  if not found then raise exception 'DIRECTIONS_SOURCE_CHANGED';end if;
 end loop;
end

