CREATE OR REPLACE FUNCTION turn_private.publish_result_v2(p_owner_id uuid, p_artifact_id uuid, p_expected_revision integer, p_idempotency_key uuid, p_task_id uuid, p_goal_id uuid, p_input_message_id uuid, p_trip_id uuid, p_trip_version integer, p_goal_version integer, p_memory_basis jsonb, p_content jsonb, p_evidence_basis jsonb, p_owner_choice boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a turn_private.result_artifacts%rowtype; r turn_private.result_revisions%rowtype;
