  or jsonb_typeof(v->'coverage') is distinct from 'string' or v->>'coverage' not in('complete_relative','partial_relative')
  or not turn_private.directions_strings_v1(v->'limitations',10,3000) or jsonb_array_length(v->'limitations')=0
  or jsonb_typeof(v->'paceSource') is distinct from 'string' or v->>'paceSource' not in('current_input','profile','none')
